"""Count within-word positions and render the position-distribution charts."""

import html
import json
import math
import re
from collections import Counter, defaultdict
from config import paths, read_template
from eva import LETTERS, GROUPED_FORMS, readable_words, tokenize

BIN_COUNT = 15
FREQUENCY_COLORS = [
    "#fff9bf",
    "#ffe28a",
    "#ffc267",
    "#ff963e",
    "#ff602e",
    "#e52722",
    "#b9002e",
]


def load_glyphs(frequency_page):
    """Read the vector labels generated by eva_frequencies.py."""
    match = re.search(
        r'<script id="glyphData" type="application/json">(.*?)</script>',
        frequency_page,
        re.S,
    )
    if match is None:
        raise ValueError("Frequency HTML is missing its embedded glyphData block")
    return json.loads(match.group(1))


def count_positions(words, mode):
    """Normalize positions to [0, 1]; put single-token words in the middle."""
    counts = Counter()
    histograms = defaultdict(lambda: [0] * BIN_COUNT)
    for word in words:
        tokens = tokenize(word, mode)
        for index, token in enumerate(tokens):
            position = index / (len(tokens) - 1) if len(tokens) > 1 else 0.5
            bin_index = min(BIN_COUNT - 1, int(position * BIN_COUNT))
            histograms[token][bin_index] += 1
            counts[token] += 1
    return counts, histograms


def render_position_chart(mode, counts, histograms, glyphs, word_count, shared=False):
    symbols = sorted(LETTERS + GROUPED_FORMS if mode == "groups" else LETTERS)
    total = sum(counts.values())
    row_count = math.ceil(len(symbols) / 2)
    width = 1120
    height = 230 + row_count * 105 + 230
    svg_parts = [
        f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {width} {height}" role="img" aria-labelledby="title desc"><title id="title">Where EVA symbols occur within words</title><desc id="desc">Position distributions for {mode}. Left is word beginning; right is word end. Each panel '
        + (
            "shares the same vertical count scale."
            if shared
            else "is scaled to its own peak; compare shape, not panel height."
        )
        + '</desc><rect width="1120" height="100%" fill="#fffdf7"/>',
        "<style>text{font-family:system-ui,sans-serif;fill:#263a37}.small{font-size:13px;fill:#62716c}.label{font-size:16px;font-family:monospace}.head{font-family:Georgia,serif;font-size:42px}.axis{stroke:#9da79e;stroke-width:1}</style>",
        '<text x="45" y="62" class="head">Where EVA symbols occur within words</text>',
        f"""<text x="45" y="98" font-size="18">Beginning → middle → end · {mode == 'groups' and 'Grouped EVA forms' or 'Individual EVA letters'}</text>""",
        f'<text x="45" y="128" class="small">{word_count:,} word occurrences · {total:,} counted tokens · Zandbergen–Landini 3b</text>',
        f'<text x="45" y="153" class="small">'
        + (
            "Shared vertical scale: absolute occurrences per position bin."
            if shared
            else "Each panel scaled to its own peak. Color shows overall frequency; height shows relative position."
        )
        + "</text>",
    ]
    global_maximum = max((max(bin_counts) for bin_counts in histograms.values()))
    for symbol_index, symbol in enumerate(symbols):
        column = symbol_index // row_count
        row_index = symbol_index % row_count
        x = 45 + column * 550
        y = 215 + row_index * 105
        plot_x = x + 100
        plot_width = 410
        plot_height = 61
        bin_counts = histograms[symbol]
        vertical_maximum = global_maximum if shared else max(bin_counts) or 1
        share = counts[symbol] / total * 100
        color = FREQUENCY_COLORS[
            next((i for (i, t) in enumerate([0.1, 0.5, 1, 2, 5, 9]) if share < t), 6)
        ]
        embedded = re.sub(
            '<svg aria-hidden="true"',
            f'<svg x="{x}" y="{y - 54}" width="66" height="66"',
            glyphs[symbol],
        )
        svg_parts.extend(
            [
                embedded,
                f'<text x="{x + 32}" y="{y + 25}" class="label" text-anchor="middle">{symbol}</text>',
                f'<line x1="{plot_x}" x2="{plot_x + plot_width}" y1="{y + plot_height}" y2="{y + plot_height}" class="axis"/>',
            ]
        )
        points = (
            [(plot_x, y + plot_height)]
            + [
                (
                    plot_x + (i + 0.5) / BIN_COUNT * plot_width,
                    y + plot_height - v / vertical_maximum * plot_height,
                )
                for (i, v) in enumerate(bin_counts)
            ]
            + [(plot_x + plot_width, y + plot_height)]
        )
        svg_parts.append(
            '<path d="M'
            + " L".join((f"{a:.2f},{b:.2f}" for (a, b) in points))
            + f' Z" fill="{color}" stroke="#665d4e" stroke-width="1.1"/>'
        )
        svg_parts.append(
            f'<text x="{plot_x}" y="{y - 9}" class="small">{counts[symbol]:,} occurrences</text><text x="{plot_x + plot_width}" y="{y - 9}" text-anchor="end" class="small">{share:.3f}%</text>'
        )
        if not counts[symbol]:
            svg_parts.append(
                f'<text x="{plot_x + plot_width / 2}" y="{y + 36}" text-anchor="middle" class="small">No occurrences in this mode</text>'
            )
    footer_y = 215 + row_count * 105
    svg_parts.append(
        f'<text x="45" y="{footer_y}" font-size="15">Color = overall token frequency</text>'
    )
    for i, c in enumerate(FREQUENCY_COLORS):
        svg_parts.append(
            f"""<rect x="{45 + i * 110}" y="{footer_y + 14}" width="110" height="15" fill="{c}"/><text x="{45 + i * 110}" y="{footer_y + 48}" class="small">{['&lt;0.1%', '0.1–0.5%', '0.5–1%', '1–2%', '2–5%', '5–9%', '≥9%'][i]}</text>"""
        )
    notes = [
        "Position = token index / (word length − 1), binned into 15 equal intervals. First and last tokens map to the endpoints.",
        "Single-token words map to the middle. Every repeated word occurrence contributes; word types are not deduplicated.",
        "Uncertain words (alternatives, rare codes, unreadable markers) are omitted in full. Inline annotations are removed.",
        "Groups: cfh, ckh, cph, cth, ch, sh use longest match; other letters remain separate. This is a convention, not a decipherment.",
        "Data: Zandbergen & Landini, ZL3b-n.txt (CC0). Glyph outlines: Gabriel Landini, EVA2.ttf (2025); private noncommercial use.",
    ]
    for i, n in enumerate(notes):
        svg_parts.append(
            f'<text x="45" y="{footer_y + 79 + i * 21}" class="small">{html.escape(n)}</text>'
        )
    return "".join(svg_parts) + "</svg>"


def main():
    data_dir, output_dir = paths(__doc__)
    words = readable_words((data_dir / "transcription.txt").read_text())
    glyphs = load_glyphs((output_dir / "voynich_eva_frequency.html").read_text())
    statistics = {}
    views = {}
    for mode in ["groups", "letters"]:
        counts, histograms = count_positions(words, mode)
        statistics[mode] = {
            "total": sum(counts.values()),
            "counts": dict(counts),
            "hist": dict(histograms),
        }
        # Render before saving JSON: absent symbols acquire zero-filled bins,
        # matching the historical output, including its zero-frequency entries.
        views[mode] = {
            "own": render_position_chart(mode, counts, histograms, glyphs, len(words)),
            "shared": render_position_chart(
                mode, counts, histograms, glyphs, len(words), shared=True
            ),
        }
        statistics[mode]["hist"] = dict(histograms)
    (output_dir / "voynich_eva_word_positions.svg").write_text(views["groups"]["own"])
    page = read_template("word_positions.html")
    payload = {"statistics": statistics, "glyphs": glyphs, "word_count": len(words)}
    page = page.replace("DEFAULT", views["groups"]["own"]).replace(
        "DATA", json.dumps(payload)
    )
    (output_dir / "voynich_eva_word_positions.html").write_text(page)
    (output_dir / "positions.json").write_text(json.dumps(statistics))
    print(f"Word positions: {len(words):,} readable word occurrences")


if __name__ == "__main__":
    main()
